1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4		<meta charset="utf-8">
5		<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
6		<meta name="description" content="A well-structured, accessible HTML5 document with modern best practices.">
7		<meta name="color-scheme" content="light dark">
8		<meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9		<meta name="theme-color" content="#121212" media="(prefers-color-scheme: dark)">
10		<meta name="author" content="ksmith@centricle.com">
11		<title>Welcome</title>
12		<style>
13			:root {
14				color-scheme: light dark;
15				--text: light-dark(#1a1a1a, #e0e0e0);
16				--text-secondary: light-dark(#555, #a0a0a0);
17				--background: light-dark(#fff, #121212);
18				--accent: light-dark(#0052a3, #5fa3ff);
19				--border: light-dark(#e0e0e0, #333);
20			}
21			*,
22			*::before,
23			*::after {
24				box-sizing: border-box;
25			}
26			html {
27				-webkit-text-size-adjust: 100%;
28				text-size-adjust: 100%;
29			}
30			@media (prefers-reduced-motion: no-preference) {
31				html {
32					scroll-behavior: smooth;
33				}
34			}
35			body {
36				display: grid;
37				grid-template-rows: auto 1fr auto;
38				min-height: 100vh;
39				min-height: 100dvh;
40				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
41				line-height: 1.6;
42				max-width: 70ch;
43				margin: 0 auto;
44				padding: max(1.25rem, env(safe-area-inset-top)) max(1.25rem, env(safe-area-inset-right)) max(1.25rem, env(safe-area-inset-bottom)) max(1.25rem, env(safe-area-inset-left));
45				color: var(--text);
46				background: var(--background);
47			}
48			h1 {
49				color: var(--accent);
50				font-size: 2rem;
51				line-height: 1.2;
52				text-wrap: balance;
53				margin: 0;
54			}
55			p {
56				text-wrap: pretty;
57				margin: 1rem 0;
58			}
59			a {
60				color: var(--accent);
61				text-underline-offset: 0.15em;
62				text-decoration-thickness: 1.5px;
63			}
64			a:hover {
65				text-decoration-thickness: 3px;
66			}
67			:focus-visible {
68				outline: 2px solid var(--accent);
69				outline-offset: 2px;
70			}
71			.skip-link {
72				position: absolute;
73				left: 0;
74				top: 0;
75				transform: translateY(-100%);
76				background: var(--accent);
77				color: var(--background);
78				padding: 0.75rem 1.5rem;
79				z-index: 1;
80				border-radius: 0 0 0.25rem 0;
81			}
82			.skip-link:focus {
83				transform: none;
84				outline-color: var(--text);
85			}
86			header {
87				padding-block: 1.5rem;
88				margin-bottom: 1.5rem;
89			}
90			main:focus {
91				outline: none;
92			}
93			footer {
94				padding-block: 1.5rem;
95				margin-top: 3rem;
96				border-top: 1px solid var(--border);
97				font-size: 0.875rem;
98				color: var(--text-secondary);
99			}
100			footer p {
101				margin: 0.5rem 0;
102			}
103			@media print {
104				.skip-link {
105					display: none;
106				}
107				body {
108					display: block;
109					min-height: 0;
110					max-width: none;
111				}
112			}
113		</style>
114	</head>
115	<body>
116		<a class="skip-link" href="#main">Skip to content</a>
117		<header>
118			<h1>Welcome</h1>
119		</header>
120		<main id="main" tabindex="-1">
121			<p>This is a well-structured, accessible HTML5 document.</p>
122			<p>
123				It uses semantic landmarks, a skip link for keyboard navigation,
124				and CSS that adapts to your light or dark mode preference.
125			</p>
126			<p>
127				Features include improved color contrast for accessibility (WCAG AA compliant),
128				better typography with consistent sizing, and smooth interactions.
129			</p>
130		</main>
131		<footer>
132			<p>&copy; 2026. All rights reserved.</p>
133		</footer>
134	</body>
135	</html>
